//! 🔁️ Selects the original edit once and rebuilds each visible operation view under full grants.
use semio_os_spr::{MutationMessage, MutationReplayOutcome};
use semio_os_spr::command::{FinalMessageSelection, MutationMessageLedgerRetirement, MutationMessageRetirement, ReplayMessageAccumulator};
use semio_os_spr::command::MessageCopyCursor;
use semio_framework_value::{ValueError,ValueRefusalKind,retained_clone::{RetainedCloneGrant,RetainedCloneProgress,RetainedCloneStep}};
use std::mem::{ManuallyDrop,size_of};
enum Phase { Select, Reserve, Visit, Copy, CloseCopy, Place, Finished }
pub struct EditMessageSettlement {pub selection:FinalMessageSelection,pub messages:ManuallyDrop<Option<Vec<MutationMessage>>>,pub phase:Phase,pub outcome:usize,pub end:usize,pub ledger:usize,pub copy:Option<MessageCopyCursor>,pub pending:Option<MutationMessage>,pub active:Option<MutationMessageRetirement>,pub retiring:Option<MutationMessageLedgerRetirement>,pub closing:bool,pub work:u64,last_close_work:u64}
fn refusal()->ValueError{ValueError::literal(ValueRefusalKind::InvariantViolated,"edit diagnostic settlement lost its original admitted owner")}
impl EditMessageSettlement {
 pub fn new(edit_id:&str,messages:&ReplayMessageAccumulator,first:usize,end:usize)->Self{Self{selection:FinalMessageSelection::new(edit_id.len(),messages.rows().len()),messages:ManuallyDrop::new(None),phase:Phase::Select,outcome:first,end,ledger:0,copy:None,pending:None,active:None,retiring:None,closing:false,work:0,last_close_work:0}}
 pub fn completed_work(&self)->u64{self.work}
 pub fn is_finished(&self)->bool{matches!(self.phase,Phase::Finished)&&!self.closing}
 pub fn messages(&self)->&[MutationMessage]{self.messages.as_ref().map_or(&[],Vec::as_slice)}
 pub fn take_messages(&mut self)->Option<Vec<MutationMessage>>{if self.is_finished(){self.messages.take()}else{None}}
 pub fn next_capacity_byte_demand(&self)->Result<usize,ValueError>{Ok(match self.phase{Phase::Select=>self.selection.next_capacity_byte_demand(),Phase::Reserve if self.outcome<self.end=>self.messages().len()*size_of::<MutationMessage>(),Phase::Copy=>self.copy.as_ref().ok_or_else(refusal)?.next_capacity_byte_demand(self.messages().get(self.ledger).ok_or_else(refusal)?)?,_=>0})}
 pub fn next_copy_byte_demand(&self,input:&ReplayMessageAccumulator)->Result<usize,ValueError>{Ok(match self.phase{Phase::Select=>self.selection.next_copy_byte_demand(input),Phase::Copy=>self.copy.as_ref().ok_or_else(refusal)?.next_copy_byte_demand(self.messages().get(self.ledger).ok_or_else(refusal)?)?,Phase::CloseCopy=>self.copy.as_ref().ok_or_else(refusal)?.next_close_copy_byte_demand()?,Phase::Place=>size_of::<MutationMessage>(),_=>0})}
 pub fn next_release_byte_demand(&self,input:&ReplayMessageAccumulator)->Result<usize,ValueError>{match self.phase{Phase::Select=>self.selection.next_release_byte_demand(input),Phase::CloseCopy=>self.copy.as_ref().ok_or_else(refusal)?.next_close_release_byte_demand(),_=>Ok(0)}}
 pub fn step(&mut self,input:&mut ReplayMessageAccumulator,outcomes:&mut[MutationReplayOutcome],grant:RetainedCloneGrant)->Result<RetainedCloneProgress,ValueError>{
  let idle=RetainedCloneProgress::default();if self.closing||self.is_finished()||grant.maximum_items==0||grant.maximum_depth==0{return Ok(idle);}if grant.maximum_capacity_bytes<self.next_capacity_byte_demand()?||grant.maximum_copy_bytes<self.next_copy_byte_demand(input)?||grant.maximum_release_bytes<self.next_release_byte_demand(input)?{return Ok(idle);}let mut p=RetainedCloneProgress{copied_items:1,..idle};
  match self.phase{
   Phase::Select=>{p=self.selection.step(input,grant)?;if self.selection.is_finished(){*self.messages=Some(self.selection.take().ok_or_else(refusal)?);self.phase=Phase::Reserve;}},
   Phase::Reserve=>{if self.outcome==self.end{self.phase=Phase::Finished;}else{let count=self.messages().len();let view=&mut outcomes[self.outcome].messages;if !view.is_empty()||view.capacity()!=0{return Err(refusal());}view.try_reserve_exact(count).map_err(|_|refusal())?;p.retained_capacity_bytes=view.capacity()*size_of::<MutationMessage>();self.ledger=0;self.phase=Phase::Visit;}},
   Phase::Visit=>{if self.ledger==self.messages().len(){self.outcome+=1;self.phase=Phase::Reserve;}else if self.messages()[self.ledger].op_index!=Some(outcomes[self.outcome].op_index){self.ledger+=1;}else{self.copy=Some(MessageCopyCursor::new());self.phase=Phase::Copy;}},
   Phase::Copy=>{let source=self.messages.as_ref().and_then(|rows|rows.get(self.ledger)).ok_or_else(refusal)?;let copy=self.copy.as_mut().ok_or_else(refusal)?;let step=copy.advance(source,grant).result?;p=step.progress();if matches!(step,RetainedCloneStep::Complete(_)){self.pending=copy.take();copy.begin_close();self.phase=Phase::CloseCopy;}},
   Phase::CloseCopy=>{let copy=self.copy.as_mut().ok_or_else(refusal)?;p=copy.close_step(grant).result?.progress();if copy.terminal_is_empty(){self.copy=None;self.phase=Phase::Place;}},
   Phase::Place=>{let view=&mut outcomes[self.outcome].messages;if view.len()==view.capacity(){return Err(refusal());}view.push(self.pending.take().ok_or_else(refusal)?);p.copied_bytes=size_of::<MutationMessage>();self.ledger+=1;self.phase=Phase::Visit;},
   Phase::Finished=>{}
  }p.copied_items=p.copied_items.max(1);self.work=self.work.saturating_add(p.copied_items as u64);Ok(p)
 }
 pub fn last_close_work(&self)->u64{self.last_close_work}
 fn close_stage(&self)->u8{if self.terminal_is_empty(){return 0}if !self.closing{return 1}if !self.selection.terminal_is_empty()&&!self.selection.is_closing(){return 2}if let Some(copy)=self.copy.as_ref(){if !copy.is_cancelled(){return 3}if !copy.is_closing(){return 4}}if !self.selection.terminal_is_empty(){return 5}if let Some(copy)=self.copy.as_ref(){return if copy.terminal_is_empty(){6}else{7}}if let Some(active)=self.active.as_ref(){return if active.terminal_is_empty(){8}else{9}}if self.pending.is_some(){return 10}if let Some(retiring)=self.retiring.as_ref(){return if retiring.terminal_is_empty(){11}else{12}}if self.messages.is_some(){return 13}0}
 pub fn next_close_work_demand(&self)->Result<u64,ValueError>{Ok(u64::from(self.close_stage()!=0))}
 pub fn next_close_copy_byte_demand(&self)->Result<usize,ValueError>{Ok(match self.close_stage(){0=>0,1|2|3|4=>size_of::<bool>(),5=>self.selection.next_close_copy_byte_demand(),6=>size_of::<Option<MessageCopyCursor>>(),7=>self.copy.as_ref().ok_or_else(refusal)?.next_close_copy_byte_demand()?,8=>size_of::<Option<MutationMessageRetirement>>(),9=>self.active.as_ref().ok_or_else(refusal)?.next_copy_byte_demand(),10=>size_of::<MutationMessage>(),11=>size_of::<Option<MutationMessageLedgerRetirement>>(),12=>self.retiring.as_ref().ok_or_else(refusal)?.next_copy_byte_demand(),13=>size_of::<Vec<MutationMessage>>(),_=>return Err(refusal())})}
 pub fn next_close_capacity_byte_demand(&self,_:usize)->Result<usize,ValueError>{Ok(0)}
 pub fn next_close_release_byte_demand(&self)->Result<usize,ValueError>{Ok(match self.close_stage(){5=>self.selection.next_close_release_byte_demand(),7=>self.copy.as_ref().ok_or_else(refusal)?.next_close_release_byte_demand()?,9=>self.active.as_ref().ok_or_else(refusal)?.next_release_byte_demand(),12=>self.retiring.as_ref().ok_or_else(refusal)?.next_release_byte_demand()?,_=>0})}
 pub fn next_close_depth_demand(&self)->Result<usize,ValueError>{Ok(match self.close_stage(){0=>0,5|9=>2,7=>self.copy.as_ref().ok_or_else(refusal)?.next_close_depth_demand()?.checked_add(1).ok_or_else(refusal)?,12=>self.retiring.as_ref().ok_or_else(refusal)?.next_depth_demand()?.checked_add(1).ok_or_else(refusal)?,_=>1})}
 pub fn close_step(&mut self,grant:RetainedCloneGrant)->Result<RetainedCloneStep,ValueError>{self.last_close_work=0;let idle=RetainedCloneProgress::default();let stage=self.close_stage();if stage==0{return Ok(RetainedCloneStep::Complete(idle))}let copy=self.next_close_copy_byte_demand()?;let release=self.next_close_release_byte_demand()?;let depth=self.next_close_depth_demand()?;if grant.maximum_items==0||grant.maximum_depth<depth||grant.maximum_copy_bytes<copy||grant.maximum_release_bytes<release{return Ok(RetainedCloneStep::Progress(idle))}let child=RetainedCloneGrant{maximum_depth:grant.maximum_depth.saturating_sub(1),..grant};let local=|bytes|RetainedCloneStep::Progress(RetainedCloneProgress{copied_items:1,copied_bytes:bytes,..idle});match stage{1=>{self.closing=true;self.last_close_work=1;Ok(local(copy))},2=>{self.selection.begin_close();self.last_close_work=1;Ok(local(copy))},3=>{self.copy.as_mut().ok_or_else(refusal)?.cancel();self.last_close_work=1;Ok(local(copy))},4=>{self.copy.as_mut().ok_or_else(refusal)?.begin_close();self.last_close_work=1;Ok(local(copy))},5=>{let progress=self.selection.close_step(child);self.last_close_work=self.selection.last_close_work();Ok(RetainedCloneStep::Progress(progress))},6=>{self.copy.take();self.last_close_work=1;Ok(local(copy))},7=>{let turn=self.copy.as_mut().ok_or_else(refusal)?.close_step(child);self.last_close_work=turn.work;turn.result.map(|step|RetainedCloneStep::Progress(step.progress()))},8=>{self.active.take();self.last_close_work=1;Ok(local(copy))},9=>{let active=self.active.as_mut().ok_or_else(refusal)?;let progress=active.close_step(child);self.last_close_work=active.last_turn_work();Ok(RetainedCloneStep::Progress(progress))},10=>{self.active=Some(MutationMessageRetirement::new(self.pending.take().ok_or_else(refusal)?));self.last_close_work=1;Ok(local(copy))},11=>{self.retiring.take();self.last_close_work=1;Ok(local(copy))},12=>{let retiring=self.retiring.as_mut().ok_or_else(refusal)?;let result=retiring.close_step(child);self.last_close_work=retiring.last_turn_work();result.map(|step|RetainedCloneStep::Progress(step.progress()))},13=>{let messages=self.messages.take().ok_or_else(refusal)?;self.retiring=Some(MutationMessageLedgerRetirement::new(String::new(),messages));self.last_close_work=1;Ok(local(copy))},_=>Err(refusal())}}
 pub fn terminal_is_empty(&self)->bool{self.selection.terminal_is_empty()&&self.messages.is_none()&&self.copy.is_none()&&self.pending.is_none()&&self.active.is_none()&&self.retiring.is_none()}
 pub(crate) fn close_cold(&mut self){while !self.terminal_is_empty(){self.close_step(RetainedCloneGrant {maximum_items:1,maximum_copy_bytes:usize::MAX,maximum_capacity_bytes:usize::MAX,maximum_release_bytes:usize::MAX,maximum_depth:usize::MAX}).expect("cold edit diagnostic settlement");}}
}
impl Drop for EditMessageSettlement{fn drop(&mut self){assert!(std::thread::panicking()||self.terminal_is_empty(),"edit diagnostic views must transfer or close exact owners");if self.terminal_is_empty(){unsafe{ManuallyDrop::drop(&mut self.messages);}}}}

